 <?php $__env->startSection('content'); ?><h1>Daftar Buku</h1><div class="card"><form method="get"><input name="q" value="<?php echo e($q); ?>" placeholder="Cari judul atau penulis"><select name="category"><option value="">Semua kategori</option><?php $__currentLoopData = $categories; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $c): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($c->id); ?>" <?php if($category==$c->id): echo 'selected'; endif; ?>><?php echo e($c->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><button>Cari/Filter</button> <a class="btn" href="<?php echo e(route('books.create')); ?>">Tambah Buku</a></form></div><table><tr><th>Judul</th><th>Penulis</th><th>Kategori</th><th>Stok</th><th>Aksi</th></tr><?php $__empty_1 = true; $__currentLoopData = $books; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $b): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><?php echo e($b->title); ?></td><td><?php echo e($b->author); ?></td><td><?php echo e($b->category->name); ?></td><td><?php echo e($b->stock); ?></td><td><a class="btn" href="<?php echo e(route('books.show',$b)); ?>">Detail</a> <a class="btn" href="<?php echo e(route('books.edit',$b)); ?>">Edit</a><form style="display:inline" method="post" action="<?php echo e(route('books.destroy',$b)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><button class="danger">Hapus</button></form></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="5">Tidak ada data.</td></tr><?php endif; ?></table><?php $__env->stopSection(); ?>

